def load_sprite(name):
    try:
        raw = base64.b64decode(EMBEDDED_IMAGES[name])
        image = pygame.image.load(io.BytesIO(raw), name + ".png")
        return image.convert_alpha()
    except Exception as err:
        print("IMAGE LOAD ERROR:", name, err)
        return None

SPRITES = {name: load_sprite(name) for name in [
    "tile_stone", "tile_blue", "tile_cracked", "tile_moss",
    "tile_rune", "tile_cobble", "tile_ice", "tile_lava",
    "knight", "goblin", "skeleton", "imp", "demon_boss",
    "torch", "coin", "potion"
]}

def blit_sprite(name, center_x, bottom_y, width, height):
    image = SPRITES.get(name)
    if image is None:
        return False
    size = (max(1, int(width)), max(1, int(height)))
    key = (name, size)
    scaled = SCALED_SPRITES.get(key)
    if scaled is None:
        scaled = pygame.transform.scale(image, size)
        SCALED_SPRITES[key] = scaled
    rect = scaled.get_rect(midbottom=(int(center_x), int(bottom_y)))
    screen.blit(scaled, rect)
    return True


def load_save():
    global high_score
    try:
        with open(SAVE_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        high_score = int(data.get("high_score", 0))
    except Exception:
        high_score = 0

def save_game():
    try:
        with open(SAVE_FILE, "w", encoding="utf-8") as f:
            json.dump({"high_score": high_score}, f)
    except Exception:
        pass

def draw_text(msg, x, y, color=WHITE, font=FONT, center=False):
    img = font.render(str(msg), True, color)
    rect = img.get_rect()
    if center:
        rect.center = (int(x), int(y))
    else:
        rect.topleft = (int(x), int(y))
    screen.blit(img, rect)

def dist(x1, y1, x2, y2):
    return math.hypot(x2 - x1, y2 - y1)

def show_message(msg):
    global message, message_timer
    message = msg
    message_timer = 100

def iso(x, y):
    # Top-down screen coordinates with a camera following the hero.
    return (int(ORIGIN_X + x*TILE - camera_x), int(ORIGIN_Y + y*TILE - camera_y))

def update_camera():
    global camera_x, camera_y
    map_w, map_h = COLS*TILE, ROWS*TILE
    view_h = MAP_VIEW_BOTTOM - MAP_VIEW_TOP
    target_x = player["x"]*TILE - W/2
    target_y = player["y"]*TILE - (MAP_VIEW_TOP + view_h/2)
    camera_x = max(0, min(max(0, map_w-W), target_x))
    camera_y = max(0, min(max(0, map_h-view_h), target_y))

def cell_blocked(x, y):
    cx, cy = int(round(x)), int(round(y))
    return cx < 0 or cy < 0 or cx >= COLS or cy >= ROWS or (cx, cy) in walls

def move_player(screen_dx, screen_dy, dt):
    # In top-down mode joystick directions match the screen directions.
    dx, dy = screen_dx, screen_dy
    length = math.hypot(dx, dy)
    if length > 1:
        dx /= length; dy /= length
    if abs(dx)+abs(dy) > 0.04:
        player["facing"] = (dx, dy)
        player["anim"] += max(1, int(dt/16.67*2))
    speed = 0.19 * min(dt/16.67, 2.0)
    nx = player["x"] + dx*speed
    ny = player["y"] + dy*speed
    if not cell_blocked(nx, player["y"]): player["x"] = nx
    if not cell_blocked(player["x"], ny): player["y"] = ny

def random_cell(min_distance=2):
    for _ in range(500):
        x = random.randint(1, COLS-2)
        y = random.randint(1, ROWS-2)
        if (x, y) in walls or (x, y) == exit_cell:
            continue
        if dist(x, y, player["x"], player["y"]) < min_distance:
            continue
        return x, y
    return (COLS-3, 2)

def create_map():
    global walls, exit_cell, torch_cells, crate_cells, map_variant
    walls = set()
    map_variant = (level - 1) % 6
    for x in range(COLS):
        walls.add((x, 0)); walls.add((x, ROWS-1))
    for y in range(ROWS):
        walls.add((0, y)); walls.add((COLS-1, y))
    exit_cell = (COLS-2, ROWS-2)

    # Every level gets a different obstacle layout, while keeping
    # a connected outer route so the exit remains reachable.
    safe = set()
    for x in range(1, COLS-1):
        safe.add((x, 1)); safe.add((x, ROWS-2))
    for y in range(1, ROWS-1):
        safe.add((1, y)); safe.add((COLS-2, y))
    density = min(0.27, 0.10 + level * 0.012)
    for y in range(2, ROWS-2):
        for x in range(2, COLS-2):
            if (x, y) in safe:
                continue
            roll = random.random()
            # Different level signatures: scattered ruins, rows, chambers,
            # cross corridors, dense crypts and lava-like obstacle clusters.
            if map_variant == 0:
                blocked = roll < density
            elif map_variant == 1:
                blocked = (x % 3 == 0 and roll < 0.55) or roll < density * 0.45
            elif map_variant == 2:
                blocked = ((x+y) % 4 == 0 and roll < 0.62) or roll < density * 0.55
            elif map_variant == 3:
                blocked = (y in (3, 5) and x not in (4, 8) and roll < 0.38) or roll < density * 0.55
            elif map_variant == 4:
                blocked = roll < min(0.34, density + 0.09)
            else:
                blocked = ((x in (3, 9) or y == 4) and roll < 0.42) or roll < density * 0.6
            if blocked:
                walls.add((x, y))

    # Randomize torches and crates on walkable cells each level.
    walkable = [(x,y) for y in range(1, ROWS-1) for x in range(1,COLS-1)
                if (x,y) not in walls and (x,y) not in ((1,1), exit_cell)]
    random.shuffle(walkable)
    torch_cells = walkable[:min(7, len(walkable))]
    crate_cells = walkable[7:10]

def add_particles(x, y, color, amount=8):
    for _ in range(amount):
        particles.append({
            "x": float(x), "y": float(y),
            "dx": random.uniform(-0.055, 0.055),
            "dy": random.uniform(-0.055, 0.055),
            "life": random.randint(16, 38),
            "color": color
        })

def update_particles(dt):
    frame_scale = min(dt / 16.67, 2.0)
    for p in particles[:]:
        p["x"] += p["dx"]*frame_scale; p["y"] += p["dy"]*frame_scale
        p["life"] -= frame_scale
        if p["life"] <= 0:
            particles.remove(p)

def new_level():
    global enemies, bullets, enemy_bullets, pickups, bombs, boss_alive
    create_map()
    enemies, bullets, enemy_bullets, pickups, bombs = [], [], [], [], []
    player["x"], player["y"] = 1.0, 1.0
    boss_alive = False
    if level % 5 == 0:
        x, y = random_cell(5)
        hp = 260 + level * 28
        enemies.append({"x":float(x), "y":float(y), "hp":hp, "max_hp":hp,
                        "speed":0.050, "boss":True, "kind":"demon", "attack":70, "attack_timer":35, "attack_flash":0, "path_timer":0, "path_bias":random.randrange(4), "path_target":(x,y)})
        boss_alive = True
    count = 3 + level * 2
    if level % 5 == 0:
        count = 4 + level
    kinds = ["goblin", "skeleton", "imp"]
    for i in range(count):
        x, y = random_cell(3)
        hp = 34 + level * 6
        kind = random.choice(kinds)
        enemies.append({"x":float(x), "y":float(y), "hp":hp, "max_hp":hp,
                        "speed":0.044 + level*0.0025, "boss":False,
                        "kind":kind, "attack":0, "attack_timer":random.randint(20,55), "attack_flash":0, "path_timer":0, "path_bias":random.randrange(4), "path_target":(x,y)})
    for _ in range(3 + level//2):
        x, y = random_cell(2)
        pickups.append({"x":float(x), "y":float(y),
                        "type":random.choice(["coin","coin","health","shield","weapon","key"])})
    show_message("LEVEL " + str(level))

def start_game():
    global level, score, coins, health, shield, weapon, state, paused
    global fire_cooldown, bomb_cooldown, damage_cooldown, message_timer, shake
    global joy_active, joy_vector, fire_held, bomb_held, finger_map
    global particles, camera_x, camera_y

    # Reset every run-specific value so Restart starts a genuinely fresh game.
    level, score, coins = 1, 0, 0
    health, shield, weapon = 100, 50, "Machine Gun"
    paused = False
    fire_cooldown = bomb_cooldown = damage_cooldown = 0
    message_timer = shake = 0
    joy_active = False
    joy_vector = [0.0, 0.0]
    fire_held = bomb_held = False
    finger_map = {}
    particles = []
    camera_x = camera_y = 0.0
    state = "playing"
    new_level()

def shoot():
    global fire_cooldown
    if fire_cooldown > 0 or not enemies:
        return
    if weapon == "Pistol":
        fire_cooldown, damage, speed, color = 24, 32, 0.22, GOLD
    elif weapon == "Magic":
        fire_cooldown, damage, speed, color = 34, 55, 0.16, PURPLE
    else:
        fire_cooldown, damage, speed, color = 8, 14, 0.23, CYAN
    target = min(enemies, key=lambda e: dist(player["x"],player["y"],e["x"],e["y"]))
    dx, dy = target["x"]-player["x"], target["y"]-player["y"]
    length = math.hypot(dx,dy)
    if length < 0.001: return
    bullets.append({"x":player["x"],"y":player["y"],"dx":dx/length*speed,
                    "dy":dy/length*speed,"damage":damage,"color":color,"life":65})

def throw_bomb():
    global bomb_cooldown
    if bomb_cooldown > 0: return
    bomb_cooldown = 100
    bombs.append({"x":player["x"],"y":player["y"],"timer":38})
    show_message("BOMB PLACED")

def finish_game(won):
    global state, high_score
    if score > high_score:
        high_score = score
        save_game()
    state = "victory" if won else "gameover"

def damage_player(amount):
    global health, shield, damage_cooldown, shake
    if damage_cooldown > 0: return
    # Shield absorbs damage first, health takes any remainder.
    absorbed = min(shield, amount)
    shield -= absorbed
    health -= (amount-absorbed)
    damage_cooldown = 28
    shake = 5
    add_particles(player["x"],player["y"],RED,9)
    if health <= 0:
        health = 0
        finish_game(False)

def find_enemy_step(e):
    """BFS path to the hero. Each enemy calculates its own route around walls."""
    sx, sy = int(round(e["x"])), int(round(e["y"]))
    gx, gy = int(round(player["x"])), int(round(player["y"]))
    if (sx, sy) == (gx, gy): return (gx, gy)
    queue = [(sx, sy)]
    came = {(sx, sy): None}
    head = 0
    while head < len(queue) and head < 500:
        cx, cy = queue[head]; head += 1
        if (cx, cy) == (gx, gy): break
        # Vary neighbour priority per enemy so they do not all queue in one lane.
        dirs = [(1,0),(-1,0),(0,1),(0,-1)]
        shift = e.get("path_bias", 0) % 4
        dirs = dirs[shift:] + dirs[:shift]
        for ox, oy in dirs:
            nx, ny = cx+ox, cy+oy
            if nx < 0 or ny < 0 or nx >= COLS or ny >= ROWS or (nx,ny) in walls or (nx,ny) in came:
                continue
            came[(nx,ny)] = (cx,cy)
            queue.append((nx,ny))
    if (gx,gy) not in came:
        return (sx, sy)
    step = (gx,gy)
    while came[step] is not None and came[step] != (sx,sy):
        step = came[step]
    return step

def update_enemies(dt):
    frame_scale = min(dt/16.67, 2.0)
    for index, e in enumerate(enemies[:]):
        e["path_timer"] = e.get("path_timer", 0) - frame_scale
        if e["path_timer"] <= 0:
            e["path_timer"] = random.uniform(9, 16)
            e["path_bias"] = e.get("path_bias", index) + random.choice([0,1,2,3])
            e["path_target"] = find_enemy_step(e)
        tx, ty = e.get("path_target", (player["x"], player["y"]))
        dx, dy = tx-e["x"], ty-e["y"]
        length = math.hypot(dx,dy)
        if length > 0.06:
            e["facing"] = (dx/length, dy/length)
            speed = e["speed"] * frame_scale
            nx = e["x"] + dx/length*speed
            ny = e["y"] + dy/length*speed
            if not cell_blocked(nx,e["y"]): e["x"] = nx
            if not cell_blocked(e["x"],ny): e["y"] = ny
        # Gentle separation: enemies spread instead of occupying one point.
        for other in enemies:
            if other is e: continue
            ox, oy = e["x"]-other["x"], e["y"]-other["y"]
            d = math.hypot(ox,oy)
            if 0.001 < d < 0.58:
                push = 0.012*frame_scale
                px, py = e["x"]+ox/d*push, e["y"]+oy/d*push
                if not cell_blocked(px,e["y"]): e["x"] = px
                if not cell_blocked(e["x"],py): e["y"] = py
        pd = dist(player["x"],player["y"],e["x"],e["y"])
        if e["boss"]:
            e["attack"] -= frame_scale
            if e["attack"] <= 0 and pd < 8:
                e["attack"] = 75
                if pd > 0.01:
                    enemy_bullets.append({"x":e["x"],"y":e["y"],"dx":(player["x"]-e["x"])/pd*0.13,"dy":(player["y"]-e["y"])/pd*0.13})
        e["attack_timer"] = max(0,e.get("attack_timer",0)-frame_scale)
        e["attack_flash"] = max(0,e.get("attack_flash",0)-frame_scale)
        if pd < (0.82 if e["boss"] else 0.68) and e["attack_timer"] <= 0:
            e["attack_timer"] = 38 if e["boss"] else 48
            e["attack_flash"] = 12
            damage_player(18 if e["boss"] else 10)

def update_bullets(dt):
    global score
    frame_scale = min(dt / 16.67, 2.0)
    for b in bullets[:]:
        b["x"] += b["dx"]*frame_scale; b["y"] += b["dy"]*frame_scale; b["life"] -= frame_scale
        if b["life"] <= 0 or cell_blocked(b["x"],b["y"]):
            bullets.remove(b); continue
        hit = None
        for e in enemies:
            if dist(b["x"],b["y"],e["x"],e["y"]) < (0.62 if e["boss"] else 0.38):
                hit = e; break
        if hit:
            hit["hp"] -= b["damage"]
            add_particles(hit["x"],hit["y"],PURPLE if hit["boss"] else RED,5)
            bullets.remove(b)
            if hit["hp"] <= 0:
                score += 500 if hit["boss"] else 100
                add_particles(hit["x"],hit["y"],GOLD,22)
                if hit["boss"]:
                    show_message("BOSS DEFEATED!")
                enemies.remove(hit)
    for b in enemy_bullets[:]:
        b["x"] += b["dx"]*frame_scale; b["y"] += b["dy"]*frame_scale
        if cell_blocked(b["x"],b["y"]):
            enemy_bullets.remove(b); continue
        if dist(b["x"],b["y"],player["x"],player["y"]) < 0.35:
            damage_player(16)
            enemy_bullets.remove(b)

def update_bombs(dt):
    global score
    frame_scale = min(dt / 16.67, 2.0)
    for b in bombs[:]:
        b["timer"] -= frame_scale
        if b["timer"] <= 0:
            add_particles(b["x"],b["y"],GOLD,35)
            for e in enemies[:]:
                if dist(b["x"],b["y"],e["x"],e["y"]) < 2.0:
                    e["hp"] -= 115
                    if e["hp"] <= 0:
                        score += 150
                        enemies.remove(e)
            bombs.remove(b)

def update_pickups():
    global health, shield, coins, score, weapon
    for item in pickups[:]:
        if dist(player["x"],player["y"],item["x"],item["y"]) < 0.46:
            kind = item["type"]
            if kind == "coin":
                coins += 1; score += 25; show_message("+1 COIN")
            elif kind == "health":
                health = min(max_health,health+30); show_message("HEALTH +30")
            elif kind == "shield":
                shield = min(100,shield+40); show_message("SHIELD +40")
            elif kind == "weapon":
                weapon = weapons[(weapons.index(weapon)+1)%len(weapons)]
                show_message(weapon.upper())
            elif kind == "key":
                score += 75; show_message("ANCIENT RELIC +75")
            add_particles(item["x"],item["y"],GOLD,9)
            pickups.remove(item)

def check_level():
    global level
    if not enemies and dist(player["x"],player["y"],exit_cell[0],exit_cell[1]) < 0.62:
        if level >= 10:
            finish_game(True)
        else:
            level += 1
            new_level()

