def diamond(cx,cy,color):
    # Retained helper name; now draws a square top-down floor tile.
    r = pygame.Rect(cx-TILE//2, cy-TILE//2, TILE, TILE)
    pygame.draw.rect(screen,color,r)
    pygame.draw.rect(screen,(27,29,38),r,1)

def draw_floor():
    palettes = [
        ["tile_stone", "tile_blue", "tile_cracked", "tile_cobble"],
        ["tile_moss", "tile_cracked", "tile_stone", "tile_rune"],
        ["tile_rune", "tile_blue", "tile_cobble", "tile_moss"],
        ["tile_cobble", "tile_stone", "tile_cracked", "tile_rune"],
        ["tile_ice", "tile_blue", "tile_stone", "tile_cracked"],
        ["tile_lava", "tile_cracked", "tile_cobble", "tile_rune"]
    ]
    tile_names = palettes[(level-1) % len(palettes)]
    for y in range(ROWS):
        for x in range(COLS):
            cx, cy = iso(x+0.5,y+0.5)
            rect = pygame.Rect(cx-TILE//2,cy-TILE//2,TILE,TILE)
            if (x,y) in walls:
                pygame.draw.rect(screen,(35,35,46),rect)
                pygame.draw.rect(screen,(103,98,108),(rect.x+2,rect.y+2,rect.w-4,rect.h-5),border_radius=4)
                pygame.draw.rect(screen,(54,52,63),(rect.x+4,rect.y+4,rect.w-8,rect.h-8),2,border_radius=3)
                pygame.draw.line(screen,(130,123,130),(rect.x+5,rect.y+5),(rect.right-6,rect.y+5),2)
            else:
                tile = tile_names[(x*3+y*5+level) % len(tile_names)]
                if not blit_sprite(tile,cx,cy+TILE//2,TILE,TILE):
                    c = STONE_A if (x+y)%2 else STONE_B
                    pygame.draw.rect(screen,c,rect)
                    pygame.draw.rect(screen,(27,29,38),rect,1)
    ex,ey=iso(exit_cell[0]+0.5,exit_cell[1]+0.5)
    pygame.draw.rect(screen,(15,25,40),(ex-15,ey-15,30,30),border_radius=5)
    pygame.draw.circle(screen,(20,115,210),(ex,ey),12)
    pygame.draw.circle(screen,(100,220,255),(ex,ey),9,2)
    pygame.draw.circle(screen,(200,250,255),(ex,ey),4)

def draw_torch(x,y):
    if not blit_sprite("torch", x, y+2, 22, 30):
        flick=random.randint(-2,2)
        pygame.draw.line(screen,(95,57,32),(x,y),(x,y-9),4)
        pygame.draw.circle(screen,(255,105,20),(x,y-12+flick),6)
        pygame.draw.circle(screen,(255,205,55),(x,y-13+flick),3)

def draw_environment():
    for x,y in torch_cells:
        sx,sy=iso(x+0.5,y+0.5)
        draw_torch(sx,sy+7)
    for x,y in crate_cells:
        sx,sy=iso(x+0.5,y+0.5)
        pygame.draw.ellipse(screen,(24,18,15),(sx-12,sy+5,24,9))
        pygame.draw.rect(screen,(104,62,34),(sx-12,sy-12,24,24),border_radius=3)
        pygame.draw.rect(screen,(54,34,25),(sx-12,sy-12,24,24),1,border_radius=3)

def draw_knight(x,y):
    bob = int(math.sin(player["anim"]*0.35)*3) if abs(player.get("facing", (0,0))[0]) + abs(player.get("facing", (0,0))[1]) > 0.04 else 0
    pygame.draw.ellipse(screen,(12,10,16),(x-17,y+8,34,10))
    image = SPRITES.get("knight")
    if image is not None:
        fx, fy = player.get("facing", (1,0))
        # Turn the hero toward the last movement direction.
        if abs(fx) >= abs(fy):
            direction = "right" if fx >= 0 else "left"
        else:
            direction = "down" if fy >= 0 else "up"
        key = ("knight_pose", direction, (76,78))
        scaled = SCALED_SPRITES.get(key)
        if scaled is None:
            base = pygame.transform.scale(image, (76,78))
            if direction == "left":
                scaled = pygame.transform.flip(base, True, False)
            elif direction == "up":
                scaled = pygame.transform.rotate(base, 90)
            elif direction == "down":
                scaled = pygame.transform.rotate(base, -90)
            else:
                scaled = base
            SCALED_SPRITES[key] = scaled
        rect = scaled.get_rect(center=(int(x), int(y+bob)))
        screen.blit(scaled, rect)
    else:
        pygame.draw.circle(screen,BLUE,(x,y),15)
    if shield>0:
        pygame.draw.circle(screen,(75,200,245),(x,y),30,2)

def draw_enemy(e):
    x,y=iso(e["x"],e["y"])
    bob=int(math.sin(pygame.time.get_ticks()/130+e["x"])*2)
    pygame.draw.ellipse(screen,(14,10,17),(x-17,y+7,34,10))
    if e["boss"]:
        sprite="demon_boss"
        sw,sh=78,76
    else:
        sprite=e.get("kind","goblin")
        sizes={"goblin":(48,52),"skeleton":(50,54),"imp":(52,52)}
        sw,sh=sizes.get(sprite,(62,68))
    image = SPRITES.get(sprite)
    if image is not None:
        fx, fy = e.get("facing", (0,1))
        size = (sw, sh)
        key = ("enemy_pose", sprite, size, "left" if abs(fx)>=abs(fy) and fx<0 else "right" if abs(fx)>=abs(fy) else "up" if fy<0 else "down")
        posed = SCALED_SPRITES.get(key)
        if posed is None:
            base = pygame.transform.scale(image, size)
            direction = key[-1]
            if direction == "left": posed = pygame.transform.flip(base, True, False)
            elif direction == "up": posed = pygame.transform.rotate(base, 90)
            elif direction == "down": posed = pygame.transform.rotate(base, -90)
            else: posed = base
            SCALED_SPRITES[key] = posed
        rect = posed.get_rect(midbottom=(int(x), int(y+18+bob)))
        screen.blit(posed, rect)
    else:
        pygame.draw.circle(screen,RED,(x,y),14)
    bw=58 if e["boss"] else 34
    ratio=max(0,e["hp"]/e["max_hp"])
    pygame.draw.rect(screen,(65,15,24),(x-bw//2,y-sh//2-9,bw,5),border_radius=2)
    pygame.draw.rect(screen,GREEN,(x-bw//2,y-sh//2-9,int(bw*ratio),5),border_radius=2)
    if e.get("attack_flash", 0) > 0:
        px, py = iso(player["x"], player["y"])
        pygame.draw.line(screen, (255,105,65), (x, y), (px, py), 3)
        pygame.draw.circle(screen, (255,190,90), (int((x+px)/2), int((y+py)/2)), 4)

def draw_pickups():
    colors={"coin":GOLD,"health":GREEN,"shield":CYAN,"weapon":PURPLE,"key":GOLD}
